import{_ as t,o,c as n,a5 as a}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"HJ86 求最大连续bit数","description":"描述 求一个int类型数字对应的二进制数字中1的最大连续数，例如3的二进制为00000011，最大连续2个1 数据范围：数据组数：1≤ t ≤5, 1≤ n ≤500000 进阶：时间复杂度： O ( logn ) ，空间复杂度： O (1) 输入描述： 输入一个int类型数字。","frontmatter":{"title":"HJ86 求最大连续bit数","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 求一个int类型数字对应的二进制数字中1的最大连续数，例如3的二进制为00000011，最大连续2个1 数据范围：数据组数：1≤ t ≤5, 1≤ n ≤500000 进阶：时间复杂度： O ( logn ) ，空间复杂度： O (1) 输入描述： 输入一个int类型数字。","sidebarWeight":45,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为入门题/HJ86 求最大连续bit数.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为入门题/HJ86 求最大连续bit数.md","filePath":"posts/前端面试与实战/03-算法训练/华为入门题/HJ86 求最大连续bit数.md"}'),c={name:"posts/前端面试与实战/03-算法训练/华为入门题/HJ86 求最大连续bit数.md"};function i(r,e,d,s,_,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<div><h1 id="hj86-求最大连续bit数" tabindex="-1">HJ86 求最大连续bit数 <a class="header-anchor" href="#hj86-求最大连续bit数" aria-label="Permalink to &quot;HJ86 求最大连续bit数&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ86 求最大连续bit数”的核心思路，并能把它用于实际开发或面试表达。 <strong>描述</strong> 求一个int类型数字对应的二进制数字中1的最大连续数，例如3的二进制为00000011，最大连续2个1 数据范围：数据组数：1≤<em>t</em>≤5, 1≤<em>n</em>≤500000 进阶：时间复杂度： <em>O</em>(<em>logn</em>) ，空间复杂度： <em>O</em>(1) <strong>输入描述：</strong> 输入一个int类型数字 <strong>输出描述：</strong> 输出转成二进制之后连续1的个数 <strong>示例1</strong> 输入： 200 ==复制== 输出： 2 ==复制== 说明： 200的二进制表示是11001000，最多有2个连续的1。</p></blockquote><p>为了找到一个整数的二进制表示中1的最大连续数，我们可以通过不断地将这个数与自己减1后的结果进行按位与操作（<code>&amp;</code>），并计数进行了多少次操作，直到这个数变为0。这种方法的核心在于，每次<code>n &amp; (n-1)</code>操作实际上都会去除<code>n</code>二进制表示中最右边的<code>1</code>，因此，通过这种方式可以有效地计算出1的连续长度。</p><p>不过，这个方法直接计算的是1的总个数，并不能直接用来计算最大连续1的个数。为了计算最大连续1的个数，我们可以遍历这个数的二进制表示，统计连续1的最大长度。</p><p>下面是Python代码示例：</p><p>def max_consecutive_ones(n):</p><h1 id="将整数转换为二进制字符串" tabindex="-1">将整数转换为二进制字符串 <a class="header-anchor" href="#将整数转换为二进制字符串" aria-label="Permalink to &quot;将整数转换为二进制字符串&quot;">​</a></h1><p>binary_str = bin(n)[2:] # bin函数返回的字符串包含前缀&#39;0b&#39;，所以使用切片[2:]去除 max_count = 0 # 连续1的最大数量 count = 0 # 当前连续1的数量 for char in binary_str: if char == &#39;1&#39;: count += 1 # 如果字符是&#39;1&#39;，增加当前计数 max_count = max(max_count, count) # 更新最大连续1的数量 else: count = 0 # 如果字符不是&#39;1&#39;，重置当前计数 return max_count</p><h1 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h1><p>n = int(input())</p><h1 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h1><p>print(max_consecutive_ones(n))</p><p>这段代码首先使用<code>bin</code>函数将整数<code>n</code>转换为二进制字符串表示，然后遍历这个字符串，使用一个计数器<code>count</code>来统计当前的连续1的个数，同时用另一个变量<code>max_count</code>来记录遇到的最大连续1的个数。每次遇到<code>&#39;1&#39;</code>字符时，<code>count</code>自增；遇到<code>&#39;0&#39;</code>字符时，将<code>count</code>重置为0。最终，<code>max_count</code>即为所求的最大连续1的个数。</p></div>',1)])])}const u=t(c,[["render",i]]);export{m as __pageData,u as default};
